// +feature: insights-dashboard
"use client";

import { useEffect, useRef, useCallback, useState, useMemo } from "react";
import { createClient } from "@connectrpc/connect";
import { getConnectTransport, getWatchTransport } from "@/lib/api/transport";
import { InsightsService } from "@/gen/session/v1/insights_pb";
import type {
  GetInsightsSummaryResponse,
  SessionTokenSummary,
  TurnTokenStat,
  FindingType,
} from "@/gen/session/v1/insights_pb";
import {
  GetInsightsSummaryRequestSchema,
  WatchInsightsRequestSchema,
  GetSessionTurnTimelineRequestSchema,
  DismissFindingRequestSchema,
} from "@/gen/session/v1/insights_pb";
import { create } from "@bufbuild/protobuf";
import { timestampFromDate } from "@bufbuild/protobuf/wkt";

export interface InsightsFilters {
  from?: Date;
  to?: Date;
  modelFilter?: string;
  sessionIdFilter?: string;
  includeOrphans?: boolean;
}

export interface UseInsightsSummaryReturn {
  summary: GetInsightsSummaryResponse | null;
  loading: boolean;
  isLiveUpdating: boolean;
  error: string | null;
  refetch: () => void;
}

/** Hook that fetches the InsightsSummary and subscribes to live updates via WatchInsights. */
export function useInsightsSummary(
  filters: InsightsFilters = {}
): UseInsightsSummaryReturn {
  const [summary, setSummary] = useState<GetInsightsSummaryResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [isLiveUpdating, setIsLiveUpdating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const abortWatchRef = useRef<AbortController | null>(null);
  const fetchCountRef = useRef(0);

  const client = useMemo(() => createClient(InsightsService, getWatchTransport()), []);

  const fetchSummary = useCallback(async () => {
    const fetchId = ++fetchCountRef.current;
    setLoading(true);
    setError(null);
    try {
      const req = create(GetInsightsSummaryRequestSchema, {
        includeOrphans: filters.includeOrphans ?? true,
        ...(filters.modelFilter && { modelFilter: filters.modelFilter }),
        ...(filters.sessionIdFilter && { sessionIdFilter: filters.sessionIdFilter }),
        ...(filters.from && { from: timestampFromDate(filters.from) }),
        ...(filters.to && { to: timestampFromDate(filters.to) }),
      });
      const res = await client.getInsightsSummary(req);
      if (fetchId === fetchCountRef.current) {
        setSummary(res);
      }
    } catch (err) {
      if (fetchId === fetchCountRef.current) {
        setError(err instanceof Error ? err.message : "Failed to load insights");
      }
    } finally {
      if (fetchId === fetchCountRef.current) {
        setLoading(false);
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filters.includeOrphans, filters.modelFilter, filters.sessionIdFilter, filters.from, filters.to]);

  const INITIAL_RETRY_DELAY_MS = 1_000;
  const MAX_RETRY_DELAY_MS = 30_000;

  /** Subscribe to WatchInsights with exponential-backoff reconnect. */
  const startWatch = useCallback(() => {
    if (abortWatchRef.current) {
      abortWatchRef.current.abort();
    }
    const abort = new AbortController();
    abortWatchRef.current = abort;

    (async () => {
      let retryDelay = INITIAL_RETRY_DELAY_MS;
      while (!abort.signal.aborted) {
        try {
          const req = create(WatchInsightsRequestSchema, {
            ...(filters.from && { from: timestampFromDate(filters.from) }),
            ...(filters.to && { to: timestampFromDate(filters.to) }),
          });
          const stream = client.watchInsights(req, { signal: abort.signal });
          retryDelay = INITIAL_RETRY_DELAY_MS;
          for await (const event of stream) {
            if (abort.signal.aborted) break;
            if (event.eventType === "update" && event.session) {
              setIsLiveUpdating(true);
              setSummary((prev) => {
                if (!prev) return prev;
                // If time filter is active, skip sessions outside the filter window
                if (filters.from || filters.to) {
                  const lastTs = event.session!.lastMessageAt;
                  if (lastTs) {
                    const ts = Number(lastTs.seconds) * 1000;
                    if (filters.from && ts < filters.from.getTime()) return prev;
                    if (filters.to && ts > filters.to.getTime()) return prev;
                  }
                }
                const key = event.session!.conversationId || event.session!.sessionId;
                const idx = prev.sessions.findIndex(
                  (s) => (s.conversationId || s.sessionId) === key
                );
                if (idx === -1) {
                  return { ...prev, sessions: [...prev.sessions, event.session!] };
                }
                const sessions = [...prev.sessions];
                sessions[idx] = event.session!;
                return { ...prev, sessions };
              });
              setIsLiveUpdating(false);
            } else if (event.eventType === "parse_complete") {
              setIsLiveUpdating(true);
              await fetchSummary();
              setIsLiveUpdating(false);
            }
          }
        } catch (err) {
          if (!abort.signal.aborted) {
            console.error("[WatchInsights] stream error, reconnecting:", err);
          }
        }
        if (!abort.signal.aborted) {
          await new Promise<void>((r) => setTimeout(r, retryDelay));
          retryDelay = Math.min(retryDelay * 2, MAX_RETRY_DELAY_MS);
        }
      }
    })();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchSummary, filters.from, filters.to]);

  useEffect(() => {
    fetchSummary();
    startWatch();

    return () => {
      abortWatchRef.current?.abort();
    };
  }, [fetchSummary, startWatch]);

  return {
    summary,
    loading,
    isLiveUpdating,
    error,
    refetch: fetchSummary,
  };
}

export interface UseSessionDetailReturn {
  summary: SessionTokenSummary | null;
  loading: boolean;
  error: string | null;
}

/**
 * Hook that fetches a single session's SessionTokenSummary by ID, for the
 * deep-linkable /insights/session-detail?sessionId= route (Epic 1.4, Story
 * 1.4.3).
 * Sets both sessionIdFilter and conversationIdFilter to the same value so an
 * orphan session (empty sessionId) is still reachable, and includeOrphans so
 * it isn't filtered out. Deliberately omits from/to — the route must resolve
 * regardless of the dashboard's global date range at the time the link was
 * created (bookmarkability, per research/features.md §5).
 */
export function useSessionDetail(sessionId: string): UseSessionDetailReturn {
  const [summary, setSummary] = useState<SessionTokenSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const client = useMemo(() => createClient(InsightsService, getConnectTransport()), []);

  useEffect(() => {
    let cancelled = false;
    if (!sessionId) {
      // An empty sessionId (e.g. "?sessionId=" absent) is not "no filter" to
      // this hook, unlike the server's GetInsightsSummary RPC, which treats an
      // empty sessionIdFilter as unset and would return every session,
      // making res.sessions[0] an arbitrary session's data. Short-circuit to
      // a not-found state instead of issuing the request.
      setSummary(null);
      setLoading(false);
      setError(null);
      return;
    }
    setLoading(true);
    setError(null);
    (async () => {
      try {
        const req = create(GetInsightsSummaryRequestSchema, {
          sessionIdFilter: sessionId,
          conversationIdFilter: sessionId,
          includeOrphans: true,
        });
        const res = await client.getInsightsSummary(req);
        if (!cancelled) setSummary(res.sessions[0] ?? null);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load session");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [sessionId, client]);

  return { summary, loading, error };
}

export interface UseSessionTurnTimelineReturn {
  turns: TurnTokenStat[];
  loading: boolean;
  error: string | null;
}

/**
 * Hook that lazily fetches per-turn token stats for a single session, keyed on
 * conversationId. No-ops (empty turns, not loading) when conversationId is
 * falsy — used by SessionDetailDrawer, fetched only when the drawer is open
 * for a given session, never batched with the list RPCs.
 */
export function useSessionTurnTimeline(
  conversationId: string | undefined
): UseSessionTurnTimelineReturn {
  const [turns, setTurns] = useState<TurnTokenStat[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const client = useMemo(() => createClient(InsightsService, getConnectTransport()), []);

  useEffect(() => {
    if (!conversationId) {
      setTurns([]);
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    (async () => {
      try {
        const res = await client.getSessionTurnTimeline(
          create(GetSessionTurnTimelineRequestSchema, { conversationId })
        );
        if (!cancelled) setTurns(res.turns);
      } catch (err) {
        if (!cancelled) {
          console.error("[GetSessionTurnTimeline] fetch error:", err);
          setError(err instanceof Error ? err.message : "Failed to load turn timeline");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [conversationId, client]);

  return { turns, loading, error };
}

/**
 * Hook that dismisses a WasteFinding by its stable finding_id (see
 * ComputeFindingID, session/tokens/findings.go), so it's excluded from future
 * GetInsightsSummary responses. The caller (FindingsPanel) is responsible for
 * removing the card from its own rendered list — this hook only performs the
 * RPC call.
 */
export function useDismissFinding() {
  const client = useMemo(() => createClient(InsightsService, getConnectTransport()), []);

  const dismissFinding = useCallback(
    async (findingId: string, sessionId: string, conversationId: string, findingType: FindingType) => {
      await client.dismissFinding(
        create(DismissFindingRequestSchema, {
          findingId,
          sessionId,
          conversationId,
          findingType,
        })
      );
    },
    [client]
  );

  return { dismissFinding };
}
